SourceCode.Declaration:
/// <summary>
/// This class updates the METAMexJournalId field on the <c>CustInvoiceTable</c> with a constant
/// </summary>
class METAMEXUpdateFreeTextInvJournal
{
}

Method.Source:
    /// <summary>
    /// Runs the class with the specified arguments.
    /// </summary>
    /// <param name = "_args">The specified arguments.</param>
    public static void main(Args _args)
    {
        CustInvoiceTable    custInvoiceTable;
        DataArea            dataArea;

        if (Global::isSystemAdministrator())
        {
            ttsbegin;
            while select forupdate crosscompany custInvoiceTable 
                where custInvoiceTable.METAMEXJournalId == ''
            {
                changecompany(custInvoiceTable.DataAreaId)
                {
                    custInvoiceTable.METAMEXJournalId = METConstants::AMEXFreeeTextInvJournalConst;
                    custInvoiceTable.doUpdate();
                }
            }
            ttscommit;
            Info("@SYS119229");
        }
    }
